#!/usr/bin/env python3
import os
import subprocess
import json
from pathlib import Path

def extract_metadata(file_path):
    """Extract metadata from image files using external tools."""
    file_path = Path(file_path)

    if not file_path.exists():
        return None

    metadata = {}

    # Extract EXIF data using exiftool
    try:
        result = subprocess.run(
            ['exiftool', '-j', str(file_path)],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            data = json.loads(result.stdout)
            metadata['exif'] = data[0] if data else {}
    except Exception as e:
        print(f"EXIF extraction failed: {e}")

    # Get file info
    metadata['filename'] = file_path.name
    metadata['size'] = file_path.stat().st_size

    return metadata

def process_directory(dir_path):
    """Process all images in a directory."""
    dir_path = Path(dir_path)
    results = []

    # Process all files matching pattern
    for file_pattern in ['*.jpg', '*.jpeg', '*.png', '*.JPG', '*.PNG']:
        for file_path in dir_path.glob(file_pattern):
            metadata = extract_metadata(file_path)
            if metadata:
                results.append(metadata)

    return results

if __name__ == '__main__':
    import sys
    if len(sys.argv) > 1:
        dir_to_process = sys.argv[1]
        output = process_directory(dir_to_process)
        print(json.dumps(output, indent=2))
    else:
        print("Usage: python3 metadata_extractor.py <directory>")
